/* כוונון אינטראקטיבי של תיבות שער בעכבר */
.shaar-drag-bar {
    position: absolute;
    top: -24px;
    right: 0;
    background: #2563eb;
    color: #ffffff;
    font-family: 'Assistant', 'Rubik', sans-serif;
    font-size: 7.5pt;
    font-weight: 700;
    padding: 2px 8px;
    border-radius: 4px 4px 0 0;
    cursor: grab;
    user-select: none;
    display: flex;
    align-items: center;
    gap: 4px;
    z-index: 50;
    box-shadow: 0 -2px 5px rgba(0, 0, 0, 0.15);
}

.shaar-drag-bar:active {
    cursor: grabbing;
