}

.handle-t {
    top: -5px;
    left: 50%;
    transform: translateX(-50%);
    cursor: ns-resize;
}

.handle-b {
    bottom: -5px;
    left: 50%;
    transform: translateX(-50%);
    cursor: ns-resize;
}

.handle-r {
    right: -5px;
    top: 50%;
    transform: translateY(-50%);
    cursor: ew-resize;
}

.handle-l {
    left: -5px;
    top: 50%;
    transform: translateY(-50%);
    cursor: ew-resize;
}

.handle-tr {
    top: -5px;
    right: -5px;
    cursor: nesw-resize;
}

.handle-tl {
    top: -5px;
    left: -5px;
    cursor: nwse-resize;
}

.handle-br {
    bottom: -5px;
    right: -5px;
    cursor: nwse-resize;
}

.handle-bl {
    bottom: -5px;
    left: -5px;
    cursor: nesw-resize;
}

body.hide-shaar-editor .shaar-drag-bar,
body.hide-shaar-editor .shaar-resize-handle {
