}

.shaar-drag-bar:active {
    cursor: grabbing;
    background: #1d4ed8;
}

.shaar-resize-handle {
    position: absolute;
    width: 9px;
    height: 9px;
    background: #2563eb;
    border: 1.5px solid #ffffff;
