* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; width: 100%; overflow: hidden; font-family: 'Assistant', 'Rubik', system-ui, sans-serif; background-color: #334155; }
body { display: flex; flex-direction: row; color: #0f172a; }

#sidebar { height: 100vh; display: flex; flex-direction: row; background: #ffffff; box-shadow: -4px 0 20px rgba(0,0,0,0.15); z-index: 100; flex-shrink: 0; position: relative; }
#text-pane { width: 440px; min-width: 320px; height: 100vh; display: flex; flex-direction: column; background: #f8fafc; border-left: 1px solid #e2e8f0; flex-shrink: 0; }
.text-pane-header { padding: 12px 14px 10px 14px; background: #ffffff; border-bottom: 1px solid #e2e8f0; display: flex; flex-direction: column; gap: 10px; }
.header-main-title { display: flex; align-items: center; gap: 8px; font-size: 11pt; font-weight: 800; color: #0f172a; }
.text-actions-bar { display: flex; gap: 6px; align-items: center; }
.btn-tool { border: none; border-radius: 6px; font-family: 'Assistant', 'Rubik', sans-serif; font-size: 8.5pt; font-weight: 700; padding: 6px 10px; cursor: pointer; transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1); display: inline-flex; align-items: center; justify-content: center; gap: 5px; white-space: nowrap; }
.btn-primary { background: #0f172a; color: #ffffff; flex: 1.2; box-shadow: 0 2px 4px rgba(15, 23, 42, 0.15); }
.btn-primary:hover { background: #1e293b; transform: translateY(-1px); }
.btn-import { background: #2563eb; color: #ffffff; flex: 1; }
.btn-import:hover { background: #1d4ed8; transform: translateY(-1px); }
.btn-secondary { background: #ffffff; color: #334155; border: 1px solid #cbd5e1; flex: 0.8; }
.btn-secondary:hover { background: #f1f5f9; border-color: #94a3b8; }
.editor-wrapper { flex: 1; padding: 10px; overflow: hidden; display: flex; flex-direction: column; }
#raw-input { flex: 1; overflow-y: auto; background: #ffffff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 14px 16px; font-family: 'David Libre', 'Frank Ruhl Libre', serif; font-size: 11pt; line-height: 1.6; color: #1e293b; direction: rtl; white-space: pre-wrap; word-wrap: break-word; outline: none; box-shadow: inset 0 1px 3px rgba(0,0,0,0.03); }
#raw-input:focus { border-color: #3b82f6; box-shadow: inset 0 1px 3px rgba(0,0,0,0.03), 0 0 0 3px rgba(59, 130, 246, 0.15); }
.editor-line { min-height: 1.4em; padding: 1px 4px; border-radius: 3px; transition: background-color 0.2s ease; }
.editor-line:hover { background-color: #f8fafc; }
.page-break-divider { display: flex; align-items: center; justify-content: center; margin: 12px 0 10px 0; position: relative; user-select: none; cursor: default; height: 24px; }
.page-break-divider::before { content: ''; position: absolute; left: 0; right: 0; top: 50%; height: 2px; background: linear-gradient(90deg, rgba(239, 68, 68, 0.2), #dc2626 25%, #dc2626 75%, rgba(239, 68, 68, 0.2)); z-index: 1; }
.divider-badge { position: relative; z-index: 2; background: #dc2626; color: #ffffff; font-family: 'Assistant', 'Rubik', sans-serif; font-size: 7.5pt; font-weight: 800; padding: 2px 12px; border-radius: 12px; box-shadow: 0 2px 5px rgba(220, 38, 38, 0.35); display: inline-flex; align-items: center; gap: 5px; letter-spacing: 0.5px; }
.badge-dot { font-size: 6pt; opacity: 0.9; }
@keyframes highlightPulse { 0% { background-color: #fef08a; transform: scale(1.01); } 50% { background-color: #fde047; } 100% { background-color: transparent; transform: scale(1); } }
.editor-target-highlight { animation: highlightPulse 1.6s ease; border-radius: 4px; }
.text-pane-footer { padding: 6px 14px; background: #ffffff; border-top: 1px solid #e2e8f0; display: flex; justify-content: space-between; align-items: center; font-size: 7.5pt; color: #64748b; font-weight: 600; }

#settings-pane { width: 440px; height: 100vh; display: flex; flex-direction: row; background: #ffffff; border-left: 1px solid #e2e8f0; transition: width 0.25s cubic-bezier(0.4, 0, 0.2, 1); overflow: hidden; flex-shrink: 0; }
#settings-pane.collapsed { width: 30px !important; min-width: 30px !important; background: #1e293b; border-left: 1px solid #0f172a; }
.collapse-strip { width: 30px; height: 100%; display: none; flex-direction: column; align-items: center; justify-content: flex-start; padding-top: 14px; cursor: pointer; background: #1e293b; color: #94a3b8; transition: all 0.2s ease; user-select: none; gap: 16px; }
.collapse-strip:hover { background: #334155; color: #f8fafc; }
#settings-pane.collapsed .collapse-strip { display: flex; }
.collapse-icon { font-size: 11pt; font-weight: bold; }
.collapse-label { writing-mode: vertical-rl; transform: rotate(180deg); font-size: 8.5pt; font-weight: 700; letter-spacing: 1.5px; white-space: nowrap; }
.settings-content { flex: 1; height: 100%; display: flex; flex-direction: column; overflow: hidden; background: #ffffff; }
#settings-pane.collapsed .settings-content { display: none; }
.settings-top-bar { padding: 10px 12px; background: #f8fafc; border-bottom: 1px solid #e2e8f0; display: flex; justify-content: space-between; align-items: center; }
