// Build a lightweight mock DOM to simulate browser environment
class MockClassList {
    constructor() { this.classes = new Set(); }
    add(...args) { args.forEach(c => this.classes.add(c)); }
    remove(...args) { args.forEach(c => this.classes.delete(c)); }
    contains(c) { return this.classes.has(c); }
    toggle(c) { if (this.classes.has(c)) { this.classes.delete(c); return false; } else { this.classes.add(c); return true; } }
}

class MockElement {
    constructor(tagName) {
        this.tagName = (tagName || 'DIV').toUpperCase();
        this.id = '';
        this.className = '';
        this.classList = new MockClassList();
        this.style = {};
        this.attributes = {};
        this.children = [];
        this.parentNode = null;
        this.innerHTML_val = '';
        this.textContent_val = '';
        this.value = '';
        this.checked = false;
        this.options = [];
        this.selectedIndex = 0;
        this.offsetHeight = 20;
        this.clientHeight = 800;
        this.scrollHeight = 20;
        this.offsetWidth = 272;
        this.offsetTop = 0;
    }
    setAttribute(k, v) { this.attributes[k] = String(v); }
    getAttribute(k) { return this.attributes[k] || null; }
    removeAttribute(k) { delete this.attributes[k]; }
    hasAttribute(k) { return k in this.attributes; }
    appendChild(c) {
        c.parentNode = this;
        this.children.push(c);
        return c;
    }
    insertBefore(newChild, refChild) {
        newChild.parentNode = this;
        const idx = this.children.indexOf(refChild);
        if (idx >= 0) this.children.splice(idx, 0, newChild);
        else this.children.push(newChild);
        return newChild;
    }
    removeChild(c) {
        const idx = this.children.indexOf(c);
        if (idx >= 0) {
            c.parentNode = null;
            this.children.splice(idx, 1);
        }
        return c;
    }
    get lastElementChild() {
        for (let i = this.children.length - 1; i >= 0; i--) {
            if (this.children[i] instanceof MockElement) return this.children[i];
        }
        return null;
    }
    get firstElementChild() {
        for (let i = 0; i < this.children.length; i++) {
            if (this.children[i] instanceof MockElement) return this.children[i];
        }
        return null;
    }
    querySelector(sel) {
        return this.querySelectorAll(sel)[0] || null;
    }
    querySelectorAll(sel) {
        const res = [];
        const test = (el) => {
            if (!el || !(el instanceof MockElement)) return;
            let match = false;
            if (sel.startsWith('#') && el.id === sel.slice(1)) match = true;
            else if (sel.startsWith('.') && (el.className.includes(sel.slice(1)) || el.classList.contains(sel.slice(1)))) match = true;
            else if (sel.toLowerCase() === el.tagName.toLowerCase()) match = true;
            else if (sel.includes('.')) {
                const parts = sel.split('.');
                if (el.tagName.toLowerCase() === parts[0].toLowerCase() || parts[0] === '') {
                    if (el.classList.contains(parts[1]) || el.className.includes(parts[1])) match = true;
                }
            }
            if (match) res.push(el);
            for (let c of el.children) test(c);
        };
        for (let c of this.children) test(c);
