}

.m1-bg-middle {
    position: absolute;
    top: 20%;
    left: 0;
    right: 0;
    height: 60%;
    background: #ffffff;
}

.m1-bg-bottom {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 20%;
    background: linear-gradient(135deg, #f2f2f2 0%, #e2e2e2 100%);
    border-top: 1px solid #d0d0d0;
}

.m1-panel {
    position: absolute;
