}

.m2-bg-middle {
    position: absolute;
    top: 18%;
    left: 0;
    right: 0;
    height: 64%;
    background: #ffffff;
    box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.06), inset 0 -2px 6px rgba(0, 0, 0, 0.06);
}

.m2-bg-bottom {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
