    background: #ffffff url("data:image/svg+xml,%3Csvg width='26' height='40' viewBox='0 0 26 40' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13,20 C4,16 2,8 2,2 C2,0 8,0 13,8 C18,0 24,0 24,2 C24,8 22,16 13,20 Z M13,20 C4,24 2,32 2,38 C2,40 8,40 13,32 C18,40 24,40 24,38 C24,32 22,24 13,20 Z M13,10 A3,3 0 1,0 13,16 A3,3 0 1,0 13,10 Z M13,30 A3,3 0 1,0 13,24 A3,3 0 1,0 13,30 Z' fill='%23888888' fill-opacity='0.45'/%3E%3C/svg%3E") repeat-y;
    flex-shrink: 0;
}

.m3-wavy-band {
    position: absolute;
    top: 14%;
    left: 0;
    right: 0;
    height: 72%;
    background: #ffffff;
    border-top: 1.5px solid #d4d4d4;
    border-bottom: 1.5px solid #d4d4d4;
}

.m3-panel {
    position: absolute;
    top: 0;
    bottom: 0;
    left: 9%;
    right: 9%;
    background: #ffffff;
    border-right: 1.5px solid #ccc;
    border-left: 1.5px solid #ccc;
    box-shadow: 0 0 25px rgba(0, 0, 0, 0.14);
    z-index: 10;
}

.m3-corner {
    position: absolute;
    width: 65px;
    height: 65px;
    fill: #111;
    z-index: 25;
}

.m3-corner.tr { top: 10mm; right: 10mm; }
.m3-corner.tl { top: 10mm; left: 10mm; transform: scaleX(-1); }
.m3-corner.br { bottom: 10mm; right: 10mm; transform: scaleY(-1); }
.m3-corner.bl { bottom: 10mm; left: 10mm; transform: scale(-1, -1); }

.sub-shaar-page, .back-shaar-page {
    position: relative;
    padding: 0;
}

.sub-shaar-bg-right {
    position: absolute;
    top: 0;
    bottom: 0;
    right: 0;
    left: 55%;
    background: #f4f4f4;
}

.back-shaar-bg-left {
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    right: 55%;
    background: #f4f4f4;
}

.theme-bounded-content {
    position: absolute;
    width: auto !important;
    height: auto !important;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    align-items: center;
    text-align: center;
    z-index: 20;
    box-sizing: border-box;
    border: 1.5px dashed rgba(37, 99, 235, 0.4);
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.theme-bounded-content:hover {
    border-color: #2563eb;
    box-shadow: 0 0 10px rgba(37, 99, 235, 0.15);
}

/* כותרת עליונה (Running Header) */
.top-header-grid {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    height: 26px;
    flex-shrink: 0;
    width: 100%;
    border-bottom: 1px solid rgba(0, 0, 0, 0.08);
    padding-bottom: 3px;
    margin-bottom: 4px;
    overflow: hidden;
}

.header-col-r, .header-col-c, .header-col-l {
    display: flex;
    align-items: center;
    height: 100%;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    box-sizing: border-box;
}

.header-col-r {
    width: var(--hdr-w-r, 33.33%);
    font-family: var(--fn-header-r);
    font-size: var(--sz-header-r);
    font-weight: 700;
}

.header-col-c {
    width: var(--hdr-w-c, 33.34%);
    font-family: var(--fn-header-c);
    font-size: var(--sz-header-c);
    justify-content: center;
}

.header-col-l {
    width: var(--hdr-w-l, 33.33%);
    font-family: var(--fn-header-l);
    font-size: var(--sz-header-l);
    font-weight: 700;
}

.top-header-grid svg,
.top-header-grid img,
.header-col-r svg, .header-col-c svg, .header-col-l svg,
.header-col-r img, .header-col-c img, .header-col-l img {
    height: 14px !important;
    max-height: 15px !important;
    width: auto !important;
    max-width: 85% !important;
    object-fit: contain !important;
    display: inline-block !important;
    vertical-align: middle !important;
}

/* כותרת 2, זרימת דף וטורים */
.title-level-2-standalone {
    font-family: var(--fn-h2);
    font-size: var(--sz-h2);
    font-weight: 700;
    text-align: center;
    margin-top: 0;
    margin-bottom: 20px;
    width: 100%;
    line-height: 1.25;
    flex-shrink: 0;
}

.h2-spacer {
    flex-basis: var(--h2-top-distance, 22%);
    flex-shrink: 0;
}

.page-body-flow {
    display: flex;
    flex-direction: column;
    width: 100%;
    position: relative;
    flex-grow: 1;
    justify-content: flex-start;
    margin-top: var(--flow-mt);
    margin-bottom: var(--flow-mb);
    min-height: 0;
}

.page-body-flow.h2-flow-page {
    margin-top: var(--flow-mt-h2, var(--flow-mt));
}

.block-2col {
    display: grid;
    grid-template-columns: var(--w-margin) var(--w-gap) var(--w-col) var(--w-gutter) var(--w-col) var(--w-gap) var(--w-margin);
    width: 100%;
    position: relative;
    align-items: start;
}

/* קו מפריד אנכי בין הטורים */
.col-gutter-divider {
    grid-column: 4;
    width: 100%;
    display: flex;
    justify-content: center;
    align-self: start;
    pointer-events: none;
    height: auto;
}

.col-rule-none { display: none !important; }
.col-rule-plain { width: 1px; background-color: #777; margin: 0 auto; }
.col-rule-dashed { width: 0; border-left: 1px dashed #777; margin: 0 auto; }
.col-rule-double { width: 3px; border-left: 1px solid #777; border-right: 1px solid #777; margin: 0 auto; }

/* כותרות 3 עד 7 וכותרות מובלעות */
.block-h3-span {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 10px !important;
    margin-right: calc(var(--w-margin) + var(--w-gap)) !important;
    margin-left: calc(var(--w-margin) + var(--w-gap)) !important;
    width: calc(100% - 2 * (var(--w-margin) + var(--w-gap))) !important;
    padding: 8px 0 4px 0;
    margin-bottom: 4px;
    flex-shrink: 0;
    box-sizing: border-box;
}

.block-h3-span .h3-title-text {
    font-family: var(--fn-h3);
    font-size: var(--sz-h3);
    font-weight: 900;
    text-align: center;
    width: auto !important;
    max-width: 80%;
    line-height: 1.22;
    flex-shrink: 1;
}

.h3-ornament-right, .h3-ornament-left {
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex-shrink: 0 !important;
}

.title-level-4 {
    font-family: var(--fn-h4);
    font-size: var(--sz-h4);
    font-weight: 900;
    text-align: center;
    margin: 9px 0 4px 0;
    line-height: 1.22;
}

.title-level-5 {
    font-family: var(--fn-h5);
