    if (ORNAMENTS_LR[styleKey]) {
        return `<span class="side-ornament-wrap" style="display:inline-flex; align-items:center; ${flipStyle} ${sizeStyle}">${ORNAMENTS_LR[styleKey].svg}</span>`;
