function toGematria(num) {
    num = parseInt(num, 10);
    if (isNaN(num) || num <= 0)
        return "";
    if (num === 15)
        return "טו";
    if (num === 16)
        return "טז";
    const hundreds = ["", "ק", "ר", "ש", "ת", "תק", "תר", "תש", "תת", "תתק"];
